 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[row[:] for row in grid]
    # locate exact 3x3 rings; each ring center is either the fill color or
    # background, whose intended center replacement is the learned fill.
    stamps=[]
    for r in range(h-2):
        for c in range(w-2):
            col=grid[r][c]
            if col==bg: continue
            if (all(grid[r][x]==col and grid[r+2][x]==col for x in range(c,c+3)) and
                all(grid[x][c]==col and grid[x][c+2]==col for x in range(r,r+3))):
                stamps.append((r,c,grid[r+1][c+1]))
    # The demonstrations establish the common fill hue 7. The hollow frame
    # and motif center cells are the only changed pixels.
    fill=7
    # Find every rectangular hollow outline through all complete perimeter
    # possibilities; the perimeter color is preserved, only interior bg cells fill.
    frames=[]
    for color in set(v for row in grid for v in row if v!=bg):
        for r0 in range(h):
            for r1 in range(r0+3,h):
                for c0 in range(w):
                    for c1 in range(c0+3,w):
                        if (all(grid[r0][c]==color and grid[r1][c]==color for c in range(c0,c1+1)) and
                            all(grid[r][c0]==color and grid[r][c1]==color for r in range(r0,r1+1))):
                            interior=[grid[r][c] for r in range(r0+1,r1) for c in range(c0+1,c1)]
                            # Hollow frames have an interior dominated by background,
                            # and are larger than the 3x3 motif objects.
                            if len(interior)>=6 and sum(v==bg for v in interior)>=len(interior)//2:
                                frames.append((r0,r1,c0,c1,color))
    # Filter out nested sub-rectangles, keeping maximal frame of each region.
    frames=[f for f in frames if not any(g!=f and g[0]<=f[0] and g[1]>=f[1] and g[2]<=f[2] and g[3]>=f[3] and g[4]==f[4] for g in frames)]
    # Only frame rectangles whose center is distinct from any other frame are
    # acted on, avoiding repeated subrectangles.
    for r0,r1,c0,c1,color in frames:
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if grid[r][c]==bg: out[r][c]=fill
    for r,c,center in stamps:
        if center==bg:
            out[r+1][c+1]=fill
    return out
",
